function createStageTimingTracker(e=()=>Date.now()){const t=e();let n=t;const r=[];const toMs=e=>Math.max(0,Math.round(e));const record=(n,i)=>{const a=e();r.push({name:n,durationMs:toMs(a-i),elapsedMs:toMs(a-t)});return a};return{mark:e=>{n=record(e,n)},measure:async(t,n)=>{const r=e();try{return await n()}finally{record(t,r)}},measureSync:(t,n)=>{const r=e();try{return n()}finally{record(t,r)}},snapshot:()=>{return{totalMs:toMs(e()-t),stages:r.slice()}}}}function formatStageTimings(e){return e.length>0?e.map(e=>`${e.name}:${e.durationMs}ms@${e.elapsedMs}ms`).join(`,`):`none`}export{formatStageTimings as n,createStageTimingTracker as t};